import { loadFont } from "@remotion/google-fonts/Jost";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// UNNO — campanha UNNO10 (Essential One, "Qualidade sem preço exagerado"). Anúncio de conversão, 9:16, 31 s.
// Roteiro em quatro cenas do briefing do cliente ((arquivo do cliente)): gancho, virada de percepção,
// desejo e oferta. Estética pedida: premium, masculina, limpa; preto, off-white e neutros; fotos reais da marca;
// sans-serif moderna (Jost, a do site), alto contraste, poucas palavras por tela; entradas secas no ritmo da trilha.
// Textos e benefícios dentro da área segura de Reels/Stories (entre 280 e 1500 px).
// Locução "o locutor" sem pausas e a 1,06× (audio/unno-vo.wav), entra em 0,15 s. Sem áudio aqui.

const { fontFamily: FONT } = loadFont("normal", { weights: ["400", "500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const UN_FPS = 30;
const VO = 0.15;
export const UN_FRAMES = 31 * UN_FPS;
const INK = "#0E0E0E";
const PAPER = "#F4F1EB";
const MUTE = "#9A958C";
const LINE = "rgba(244,241,235,0.28)";
// a logo oficial, direto do site da marca (o briefing pede para não redesenhar); invertida sobre fundo escuro
const LOGO = "https://vistaunno.com.br/__l5e/assets-v1/e5d19632-beb4-45f3-a9e6-e6197453f2db/unno-logo.png";
const photo = (n: number) => staticFile(`unno/f${n}.jpg`);
const DIM: Record<number, [number, number]> = { 1: [1086, 1448], 2: [1086, 1448], 3: [1086, 1448], 4: [1122, 1402], 5: [1122, 1402], 6: [1122, 1402], 7: [1122, 1402] };

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const IN_OUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const io = (t: number, a: number, d = 0.5) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: IN_OUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const v = (s: number) => s + VO;
const clamp = (x: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, x));

// foto real da marca num quadro w×h: cobre o quadro, com zoom e ponto de foco (frações da foto)
const Shot: React.FC<{ n: number; w: number; h: number; fx: number; fy: number; z: number; style?: React.CSSProperties; filter?: string }> = ({ n, w, h, fx, fy, z, style, filter }) => {
  const [iw, ih] = DIM[n];
  const s = Math.max(w / iw, h / ih) * z;
  const W = iw * s;
  const H = ih * s;
  return (
    <div style={{ position: "absolute", width: w, height: h, overflow: "hidden", background: INK, ...style }}>
      <Img src={photo(n)} style={{ position: "absolute", width: W, height: H, left: clamp(w / 2 - fx * W, w - W, 0), top: clamp(h / 2 - fy * H, h - H, 0), filter }} />
    </div>
  );
};
// palavra que entra seca: aparece em 2 quadros, com um recuo curto de escala
const Hit: React.FC<{ t: number; at: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ t, at, children, style }) => (
  <div style={{ opacity: t >= at ? 1 : 0, transform: `scale(${(1 + (1 - k(t, at, 0.22)) * 0.16).toFixed(4)})`, whiteSpace: "nowrap", ...style }}>{children}</div>
);
const BIG: React.CSSProperties = { fontFamily: FONT, fontWeight: 700, textTransform: "uppercase", color: PAPER, letterSpacing: "0.005em", lineHeight: 1.02 };
const SMALL: React.CSSProperties = { fontFamily: FONT, fontWeight: 500, textTransform: "uppercase", color: PAPER, letterSpacing: "0.3em" };
const Col: React.FC<{ top: number; gap?: number; children: React.ReactNode; style?: React.CSSProperties }> = ({ top, gap = 0, children, style }) => (
  <div style={{ position: "absolute", left: 0, right: 0, top, display: "flex", flexDirection: "column", alignItems: "center", gap, ...style }}>{children}</div>
);
const Logo: React.FC<{ w: number; dark?: boolean; style?: React.CSSProperties }> = ({ w, dark = true, style }) => <Img src={LOGO} style={{ width: w, filter: dark ? "invert(1) brightness(1.6)" : undefined, ...style }} />;
// clarão de corte: 3 quadros
const Flash: React.FC<{ t: number; at: number; c?: string }> = ({ t, at, c = PAPER }) => (t >= at && t < at + 0.14 ? <AbsoluteFill style={{ background: c, opacity: 0.55 * (1 - (t - at) / 0.14), zIndex: 20 }} /> : null);

// ───────── cena 1 (0–3,4 s): gancho ─────────
const Hook: React.FC<{ t: number }> = ({ t }) => {
  const cut = v(2.16);
  if (t >= cut)
    return (
      <>
        <Shot n={6} w={1080} h={1920} fx={0.5} fy={0.4} z={mix(1.16, 1.04, k(t, cut, 1.4))} />
        <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(14,14,14,0.5) 0%, rgba(14,14,14,0) 26%, rgba(14,14,14,0) 56%, rgba(14,14,14,0.86) 100%)" }} />
        <Col top={1260} gap={10}>
          <Hit t={t} at={v(2.3)} style={{ ...SMALL, fontSize: 34 }}>vestir</Hit>
          <Hit t={t} at={v(2.58)} style={{ ...BIG, fontSize: 122 }}>qualidade?</Hit>
        </Col>
        <Flash t={t} at={cut} />
      </>
    );
  return (
    <AbsoluteFill style={{ background: INK }}>
      <div style={{ position: "absolute", inset: 0, transform: `scale(${(1 + lin(t, 0, cut) * 0.07).toFixed(4)})` }}>
        <Col top={520} gap={8}>
          <div style={{ ...SMALL, fontSize: 34, color: MUTE, opacity: k(t, 0, 0.3), marginBottom: 30 }}>quem disse?</div>
          <Hit t={t} at={0.03} style={{ ...BIG, fontSize: 146 }}>Qualidade</Hit>
          <Hit t={t} at={v(0.82)} style={{ ...BIG, fontSize: 112, color: MUTE }}>não precisa</Hit>
          <Hit t={t} at={v(1.14)} style={{ ...BIG, fontSize: 168 }}>custar</Hit>
          <Hit t={t} at={v(1.58)} style={{ ...BIG, fontSize: 240 }}>caro.</Hit>
        </Col>
      </div>
      {/* linha de luz varrendo o quadro: o fundo nunca fica parado */}
      <div style={{ position: "absolute", left: -400 + lin(t, 0, cut) * 1900, top: -200, width: 220, height: 2400, background: "linear-gradient(90deg, rgba(244,241,235,0) 0%, rgba(244,241,235,0.07) 50%, rgba(244,241,235,0) 100%)", transform: "rotate(14deg)" }} />
    </AbsoluteFill>
  );
};

// ───────── cena 2 (3,4–9,4 s): não é sobre preço, é sobre qualidade ─────────
const Turn: React.FC<{ t: number }> = ({ t }) => {
  const a = 3.4;
  const b = v(6.3); // "Tá no tecido…"
  if (t < b) {
    const drop = io(t, v(5.6), 0.55);
    const swing = Math.sin((t - a) * 4.2) * 7 * (1 - lin(t, a, v(5.3)) * 0.6);
    const strike = io(t, v(5.11), 0.3);
    return (
      <AbsoluteFill style={{ background: INK }}>
        <Col top={330}>
          <Hit t={t} at={v(3.34)} style={{ ...SMALL, fontSize: 34, color: MUTE }}>qualidade de verdade</Hit>
        </Col>
        {/* a etiqueta de preço alto: balança no barbante, é riscada e cai */}
        <div style={{ position: "absolute", left: 540, top: 330, width: 0, height: 0, transformOrigin: "0 0", transform: `rotate(${swing.toFixed(2)}deg) translateY(${(drop * 1700 - (1 - k(t, a + 0.05, 0.5)) * 900).toFixed(1)}px) rotate(${(drop * 24).toFixed(1)}deg)` }}>
          <div style={{ position: "absolute", left: -2, top: 0, width: 4, height: 170, background: MUTE }} />
          <div style={{ position: "absolute", left: -210, top: 160, width: 420, height: 580, borderRadius: 26, background: PAPER, boxShadow: "0 40px 90px rgba(0,0,0,0.6)", display: "flex", flexDirection: "column", alignItems: "center" }}>
            <div style={{ width: 44, height: 44, borderRadius: 22, background: INK, marginTop: 34 }} />
            <div style={{ ...SMALL, color: MUTE, fontSize: 28, marginTop: 70 }}>preço</div>
            <div style={{ position: "relative", marginTop: 26 }}>
              <div style={{ fontFamily: FONT, fontWeight: 700, fontSize: 124, color: INK, letterSpacing: "-0.02em", lineHeight: 1, whiteSpace: "nowrap" }}>
                <span style={{ fontSize: 54, verticalAlign: "top", marginRight: 8 }}>R$</span>150<span style={{ fontSize: 54, verticalAlign: "top" }}>,00</span>
              </div>
              <div style={{ position: "absolute", left: -20, right: -20, top: "52%", height: 12, background: INK, transform: `rotate(-8deg) scaleX(${strike})`, transformOrigin: "0 50%" }} />
            </div>
            <div style={{ width: 240, height: 4, background: "#D9D4CA", marginTop: 60 }} />
            <div style={{ width: 170, height: 4, background: "#D9D4CA", marginTop: 22 }} />
            {/* marca pequena no pé da etiqueta, em baixo contraste (pedido do cliente) */}
            <svg width={44} height={36} viewBox="0 0 44 36" fill="none" stroke="#B8B2A6" strokeWidth={4} strokeLinecap="round" style={{ position: "absolute", right: 34, bottom: 30 }}>
              <path d="M6 12 H38 M6 24 H38 M28 4 L16 32" />
            </svg>
          </div>
        </div>
        <Col top={1150} gap={4}>
          <Hit t={t} at={v(5.11)} style={{ ...BIG, fontSize: 112 }}>Não é sobre</Hit>
          <Hit t={t} at={v(5.55)} style={{ ...BIG, fontSize: 200 }}>preço.</Hit>
        </Col>
      </AbsoluteFill>
    );
  }
  // "Tá no tecido, no conforto e no caimento": três fotos, uma palavra em cada
  const beats: { at: number; word: string; n: number; fx: number; fy: number; z0: number; z1: number; fy1?: number }[] = [
    { at: b, word: "Tecido.", n: 5, fx: 0.5, fy: 0.36, z0: 2.5, z1: 2.9 },
    { at: v(7.49) - 0.06, word: "Conforto.", n: 3, fx: 0.57, fy: 0.3, z0: 1.3, z1: 1.42 },
    { at: v(8.47) - 0.06, word: "Caimento.", n: 7, fx: 0.48, fy: 0.4, z0: 1.12, z1: 1.0, fy1: 0.56 },
  ];
  const i = t < beats[1].at ? 0 : t < beats[2].at ? 1 : 2;
  const B = beats[i];
  const end = i < 2 ? beats[i + 1].at : 9.4;
  const p = lin(t, B.at, end);
  return (
    <>
      <Shot n={B.n} w={1080} h={1920} fx={B.fx} fy={mix(B.fy, B.fy1 ?? B.fy, p)} z={mix(B.z0, B.z1, p)} filter={i === 0 ? "contrast(1.12) saturate(1.05)" : undefined} />
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(14,14,14,0.62) 0%, rgba(14,14,14,0) 26%, rgba(14,14,14,0) 54%, rgba(14,14,14,0.88) 100%)" }} />
      <Col top={1150}>
        <div style={{ ...SMALL, fontSize: 36, opacity: k(t, b, 0.2) }}>é sobre qualidade.</div>
        <div style={{ display: "flex", gap: 14, marginTop: 24 }}>
          {[0, 1, 2].map((j) => (
            <div key={j} style={{ width: j === i ? 90 : 36, height: 6, background: j <= i ? PAPER : LINE }} />
          ))}
        </div>
      </Col>
      <Col top={1264}>
        <Hit key={i} t={t} at={B.at + 0.08} style={{ ...BIG, fontSize: i === 0 ? 180 : 138 }}>{B.word}</Hit>
      </Col>
      <Flash t={t} at={B.at} />
    </>
  );
};

// ───────── cena 3 (9,4–14,4 s): três cores, lado a lado ─────────
const Want: React.FC<{ t: number }> = ({ t }) => {
  const a = 9.4;
  const s2 = io(t, v(10.78) - 0.1, 0.5);
  const s3 = io(t, v(12.58) - 0.1, 0.5);
  const n = 1 + s2 + s3;
  const w = 1080 / n;
  const cols: { n: number; fx: number; fy: number; name: string; on: number }[] = [
    { n: 4, fx: 0.46, fy: 0.5, name: "Merlot", on: 1 },
    { n: 7, fx: 0.5, fy: 0.5, name: "Oceânico", on: s2 },
    { n: 5, fx: 0.5, fy: 0.5, name: "Duna", on: s3 },
  ];
  const push = lin(t, a, 14.4);
  return (
    <AbsoluteFill style={{ background: INK }}>
      {cols.map((c, i) => {
        const left = i === 0 ? 0 : i === 1 ? w : w * 2;
        return c.on > 0.001 ? (
          <div key={i} style={{ position: "absolute", left, top: 0, width: i === 2 ? 1080 - left : w + 1, height: 1920, overflow: "hidden" }}>
            <Shot n={c.n} w={Math.max(360, i === 2 ? 1080 - left : w + 1)} h={1920} fx={c.fx} fy={c.fy} z={1.04 + push * 0.09 + (1 - c.on) * 0.2} />
            <div style={{ position: "absolute", left: 0, top: 0, bottom: 0, width: 3, background: INK, opacity: i ? 1 : 0 }} />
            <div style={{ position: "absolute", left: 0, right: 0, top: 1096, textAlign: "center", ...SMALL, fontSize: 28, opacity: i === 0 ? k(t, a + 0.3, 0.4) : c.on, textShadow: "0 2px 14px rgba(0,0,0,0.6)" }}>{c.name}</div>
          </div>
        ) : null;
      })}
      <AbsoluteFill style={{ background: "linear-gradient(180deg, rgba(14,14,14,0.5) 0%, rgba(14,14,14,0) 24%, rgba(14,14,14,0) 52%, rgba(14,14,14,0.9) 100%)" }} />
      <Col top={1190} gap={6}>
        <Hit t={t} at={v(9.77)} style={{ ...BIG, fontSize: 108 }}>O essencial,</Hit>
        <Hit t={t} at={v(10.94)} style={{ ...BIG, fontSize: 64, color: PAPER }}>elevado ao</Hit>
        <Hit t={t} at={v(12.58)} style={{ ...BIG, fontSize: 86 }}>extraordinário.</Hit>
      </Col>
      <Flash t={t} at={a} />
    </AbsoluteFill>
  );
};

// ───────── cena 4 (14,4–31 s): a oferta, peça por peça, até o quadro final legível ─────────
const Offer: React.FC<{ t: number }> = ({ t }) => {
  const a = 14.4;
  const P = v(17.15) - 0.05; // "dez por cento"
  const C = v(18.63); // "com o cupom"
  const F = v(20.79) - 0.05; // "frete grátis"
  const H = v(24.3) - 0.05; // "recebe em até 24 horas"
  const U = v(26.56) - 0.05; // "aproveita agora no site"
  const up = io(t, C - 0.1, 0.5); // o 10% OFF sobe para dar lugar ao cupom
  const code = "UNNO10".slice(0, Math.floor(lin(t, v(19.31) - 0.1, v(19.31) + 0.45) * 6.99));
  const bg = t < F ? 6 : t < U ? 7 : 4;
  const bgA = t < F ? a : t < U ? F : U;
  return (
    <AbsoluteFill style={{ background: INK }}>
      {/* a camiseta continua na tela, escurecida, com movimento lento */}
      <Shot n={bg} w={1080} h={1920} fx={0.5} fy={0.42} z={1.1 + lin(t, bgA, bgA + 6) * 0.2} filter="brightness(0.36) saturate(0.75)" style={{ opacity: k(t, bgA, 0.5) }} />
      <AbsoluteFill style={{ background: "radial-gradient(90% 60% at 50% 46%, rgba(14,14,14,0.6) 0%, rgba(14,14,14,0.2) 100%)" }} />
      {/* luz varrendo e faixa corrida: a oferta fica legível e o quadro nunca para */}
      <div style={{ position: "absolute", left: -500 + (((t - a) * 420) % 2200), top: -200, width: 260, height: 2400, background: "linear-gradient(90deg, rgba(244,241,235,0) 0%, rgba(244,241,235,0.07) 50%, rgba(244,241,235,0) 100%)", transform: "rotate(14deg)" }} />
      <div style={{ position: "absolute", left: 0, right: 0, top: 1490, height: 62, borderTop: `2px solid ${LINE}`, borderBottom: `2px solid ${LINE}`, overflow: "hidden", opacity: k(t, P, 0.5) }}>
        <div style={{ position: "absolute", left: -(((t - a) * 150) % 1500), top: 0, height: 58, display: "flex", alignItems: "center", whiteSpace: "nowrap", ...SMALL, fontSize: 24, letterSpacing: "0.26em", color: MUTE }}>
          {Array.from({ length: 4 }, (_, i) => (
            <span key={i} style={{ width: 1500, flexShrink: 0 }}>só hoje em Aracaju&nbsp;&nbsp;•&nbsp;&nbsp;10% off&nbsp;&nbsp;•&nbsp;&nbsp;cupom UNNO10&nbsp;&nbsp;•&nbsp;&nbsp;</span>
          ))}
        </div>
      </div>
      <div style={{ position: "absolute", inset: 0, transform: `scale(${(1 + lin(t, a, 31) * 0.035).toFixed(4)})`, transformOrigin: "50% 45%" }}>
        {/* "SÓ HOJE EM ARACAJU": abre grande e vira a linha de cima */}
        {t < P ? (
          <Col top={660} gap={6} style={{ transform: `scale(${(1 + lin(t, a, P) * 0.1).toFixed(4)})`, transformOrigin: "50% 160px" }}>
            <Hit t={t} at={v(14.52)} style={{ ...BIG, fontSize: 184 }}>Só hoje</Hit>
            <Hit t={t} at={v(15.86)} style={{ ...BIG, fontSize: 116, color: PAPER }}>em Aracaju</Hit>
          </Col>
        ) : (
          <Col top={mix(560, 392, up)}>
            <div style={{ ...SMALL, fontSize: 40, opacity: k(t, P, 0.2) }}>só hoje em Aracaju</div>
          </Col>
        )}
        {t >= P ? (
          <Col top={mix(640, 458, up)} style={{ transform: `scale(${(1 + 0.02 * Math.sin((t - P) * 4.2)).toFixed(4)})` }}>
            <Hit t={t} at={P} style={{ ...BIG, fontSize: mix(212, 196, up), letterSpacing: "-0.01em" }}>10% off</Hit>
          </Col>
        ) : null}
        {/* cupom */}
        {t >= C - 0.05 ? (
          <Col top={742}>
            <div style={{ width: 800, height: 176, boxSizing: "border-box", border: `4px dashed ${PAPER}`, borderRadius: 22, display: "flex", alignItems: "center", justifyContent: "center", gap: 34, opacity: t >= C ? 1 : 0, transform: `scale(${(1 + (1 - k(t, C, 0.25)) * 0.12).toFixed(4)})`, background: "rgba(14,14,14,0.55)" }}>
              <div style={{ ...SMALL, fontSize: 30, color: MUTE, letterSpacing: "0.2em" }}>cupom</div>
              <div style={{ fontFamily: FONT, fontWeight: 700, fontSize: 104, color: PAPER, letterSpacing: "0.08em", minWidth: 480, lineHeight: 1 }}>
                {code}
                <span style={{ opacity: code.length < 6 && Math.sin(t * 18) > 0 ? 1 : 0, fontWeight: 400 }}>|</span>
              </div>
            </div>
          </Col>
        ) : null}
        {/* frete grátis e 24 h */}
        <Col top={972} gap={14}>
          <Hit t={t} at={F} style={{ ...BIG, fontSize: 80 }}>Frete grátis*</Hit>
          <Hit t={t} at={H} style={{ ...BIG, fontSize: 72 }}>
            Receba em até <span style={{ borderBottom: `6px solid ${PAPER}` }}>24h</span>
          </Hit>
        </Col>
        {/* endereço fixo */}
        {t >= U ? (
          <Col top={1228}>
            <div style={{ background: PAPER, color: INK, fontFamily: FONT, fontWeight: 600, fontSize: 62, borderRadius: 60, padding: "20px 60px 24px", letterSpacing: "0.01em", transform: `scale(${(1 + (1 - k(t, U, 0.25)) * 0.14 + 0.012 * Math.sin((t - U) * 5)).toFixed(4)})` }}>vistaunno.com.br</div>
          </Col>
        ) : null}
        <div style={{ position: "absolute", left: 0, right: 0, top: 1404, textAlign: "center", fontFamily: FONT, fontWeight: 400, fontSize: 32, color: PAPER, opacity: 0.9 * k(t, F + 0.3, 0.4) }}>*Frete grátis acima de R$ 99 em Aracaju.</div>
        <Col top={276}>
          <Logo w={220} style={{ opacity: k(t, P, 0.4) }} />
        </Col>
      </div>
      <Flash t={t} at={a} c={INK} />
      <Flash t={t} at={P} />
    </AbsoluteFill>
  );
};

// ───────── montagem: cortes secos ─────────
const SCENES: { C: React.FC<{ t: number }>; at: number }[] = [
  { C: Hook, at: 0 },
  { C: Turn, at: 3.4 },
  { C: Want, at: 9.4 },
  { C: Offer, at: 14.4 },
];
export const Unno: React.FC = () => {
  const f = useCurrentFrame();
  const t = f / UN_FPS;
  return (
    <AbsoluteFill style={{ background: INK }}>
      {SCENES.map((s, i) => {
        const next = i + 1 < SCENES.length ? SCENES[i + 1].at : 1e9;
        return t >= s.at && t < next ? (
          <AbsoluteFill key={i} style={{ overflow: "hidden" }}>
            <s.C t={t} />
          </AbsoluteFill>
        ) : null;
      })}
    </AbsoluteFill>
  );
};

import React from "react";
import { Composition, registerRoot } from "remotion";
import { UN_FPS, UN_FRAMES, Unno as UnnoV1 } from "./UnnoV1";

const Root: React.FC = () => (
  <>
    <Composition id="UnnoV1" component={UnnoV1} durationInFrames={UN_FRAMES} fps={UN_FPS} width={1080} height={1920} />
  </>
);
registerRoot(Root);
